script:
var doc = Document;
// Goal: build in a fresh scratch project, then tidy up -- never in the user's model.
// Needs execute_script { "confirm_lifecycle_actions": true } for the Close in step 6.

// 1. Create the document from Revit's default project template. It is HEADLESS: no
//    window, list_instances shows it with active:false, and UIDocument is null when a
//    run is routed at it. It outlives this run until something closes it.
var scratch = Connector.CreateProjectDocument();
// Keep the title: it is how a later run finds and closes the document if this one
// stops early. (The "cleanup-title=" line is the repo sweep's convention for closing
// scratch documents; an agent should return the title instead -- see step 6.)
System.Console.WriteLine("cleanup-title=" + scratch.Title + ";");

// 2. Write into it in the SAME run: WithTransaction works on any open document,
//    not only the routed one. The block is committed when it ends.
var levelId = Connector.WithTransaction(scratch, () => {
  var lvl = Autodesk.Revit.DB.Level.Create(scratch, 12.0);
  lvl.Name = "Scratch L1";
  return lvl.Id.Value;
});

// 3. Read it back (no block needed) to prove the commit; the write also survives
//    into later runs -- that is what makes the document useful.
int scratchLevels = new Autodesk.Revit.DB.FilteredElementCollector(scratch)
    .OfClass(typeof(Autodesk.Revit.DB.Level)).GetElementCount();

// 4. On a LATER run, address it directly: call list_instances, find the document by
//    title, and pass its document_id to execute_script. There `Document` is this
//    scratch document and UIDocument is null. An id that matches no open document
//    fails with document-not-found plus an open_documents candidate list.
//    Finding it by title from any run also works:
Autodesk.Revit.DB.Document byTitle = null; int matches = 0;
foreach (Autodesk.Revit.DB.Document d in UIApplication.Application.Documents) {
  if (d.Title == scratch.Title) { byTitle = d; matches++; }
}

// 5. Closing: a document the run wrote to has the run's group open, so Close is
//    refused until Connector.Settle(doc, keep) ends the group in the stated
//    direction. Close(false) on an unsaved document discards it either way; to keep
//    the work, SaveAs first (lifecycle-settle-save-close). Close must be called from a
//    run routed at ANOTHER document -- routed at the scratch document itself, Close
//    fails for that call only (`Document.Close` on the routed document is refused).
//    Read anything you still need BEFORE closing: after Close the wrapper is dead and
//    every member throws "The referenced object is not valid".
string scratchTitle = scratch.Title;
bool createdUnsaved = string.IsNullOrEmpty(scratch.PathName);
Connector.Settle(scratch, false);
scratch.Close(false);

// 6. Verify it is gone from Application.Documents (by the remembered title).
int stillOpen = 0;
foreach (Autodesk.Revit.DB.Document d in UIApplication.Application.Documents) {
  if (d.Title == scratchTitle) stillOpen++;
}
return new {
  scratchTitle,
  createdUnsaved,
  levelId,
  scratchLevels,           // template levels + 1
  foundByTitle = matches,  // 1
  stillOpen                // 0
};
